require dirname(__DIR__).'/includes/bootstrap.php';
$page='admin';
$section='payments';
require ROOT.'/includes/page-start.php';
 ?>
<p class="muted"><?=e(t('Payment verification is manual. Mark refunded only after issuing the actual refund outside this website.'))?></p><div class="table-wrap"><table><thead><tr><th><?=e(t('Booking / receipt'))?></th><th><?=e(t('Payment'))?></th><th><?=e(t('Status / note'))?></th><th><?=e(t('Review'))?></th></tr></thead><tbody><?php foreach(all('SELECT p.*,b.reference,b.expires_at,u.name FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN users u ON u.id=b.user_id ORDER BY p.id DESC LIMIT 200') as $p): ?><tr><td><?=e($p['reference'])?><br><?=e($p['name'])?><br><a class="text-link" href="<?=e(url('proof',['id'=>$p['id']]))?>" data-receipt="<?=e($p['id'])?>" data-endpoint="<?=e(asset('api/payment.php'))?>"><?=e(t('View receipt ↗'))?></a></td><td><?=money($p['amount'])?><br><?=e(strtoupper($p['method']))?><br><small><?=e($p['transaction_ref'])?></small></td><td><span class="badge"><?=e(t(str_replace('_',' ',$p['status'])))?></span><p><?=e($p['admin_note'])?></p><?php if($p['status']==='submitted'): ?><small><?=e(t('Hold:'))?> <?=e($p['expires_at'])?> <?=e(t('UTC'))?></small><?php endif ?></td><td><?php if(in_array($p['status'],['submitted','refund_due'])): ?><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="admin_payment"><input type="hidden" name="id" value="<?=e($p['id'])?>"><select name="decision"><?php if($p['status']==='submitted'): ?><option value="verify"><?=e(t('Verify payment'))?></option><option value="reject"><?=e(t('Reject proof'))?></option><?php else: ?><option value="refunded"><?=e(t('Mark manually refunded'))?></option><?php endif ?></select><input name="note" maxlength="500" placeholder="<?=e(t('Review / refund note'))?>"><button class="button small"><?=e(t('Save review'))?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div>

<?php require ROOT.'/includes/page-end.php'; ?>
